 {journeyStep===2&&<><div className="detail-emblem"><BookOpen size={40}/></div><h2>{t('المعنى، ومعه مصدره.','The meaning, with its source.')}</h2>{journeyClaims[2]&&<ClaimView language={prefs.lang} sources={content?.sources||[]} claim={journeyClaims[2]}/>}<button className="primary" onClick={advanceJourney}>{t('واصل الاكتشاف','Keep exploring')}</button></>}
