 {journeyStep===4&&<><span className="learning-kicker">{t('مطابقة','MAKE A CONNECTION')} {Math.min(matchIndex+1,journey.matching.pairs.length)} / {journey.matching.pairs.length}</span><h2>{t('صل النص بلحظته.','Match the text to its moment.')}</h2>{matchIndex<journey.matching.pairs.length?<>{(()=>{const c=journeyClaims.find(c=>c.claimId===journey.matching.pairs[matchIndex].claimId);return c?<ClaimView language={prefs.lang} sources={content?.sources||[]} claim={c}/>:null;})()}<div className="match-options">{[...new Set(journeyClaims.map(c=>c.momentId))].map(momentId=><button className="outlined" key={momentId} onClick={()=>{if(momentId===journey.matching.pairs[matchIndex].moment){setMatchIndex(i=>i+1);setFeedback(t('رابط جميل.','A thoughtful connection.'));haptic();}else setFeedback(t('لننظر إلى النص مرة أخرى.','Let’s look at the text once more.'));}}>{momentName(momentId)}</button>)}</div></>:<div className="matched"><Check size={50}/><h3>{t('وصلت المعنى بلحظته.','You matched the meaning to its moment.')}</h3></div>}{feedback&&<p className="feedback" role="status">{feedback}</p>}<button className="primary" disabled={matchIndex<journey.matching.pairs.length} onClick={advanceJourney}>{t('إلى ختام الرحلة','Finish the journey')}</button></>}
