 {view==='passport'&&<><PersonalMomentList records={personalMoments} language={prefs.lang} onOpen={r=>personalFlow.current?.open(r.learned?'saved':'meaning',r.momentId,r)}/><div className="passport-summary"><span><b>{stamps.filter(s=>s.type!=='visit-demo').length}</b> {t('لحظات فهم','moments understood')}</span><span className="badge"><ShieldCheck size={14}/>{t('على جهازك فقط','Only on this device')}</span></div><section className="passport-book" key={page}><div className="passport-top"><Compass size={25}/><span>LAHZA PASSPORT</span><span>{page+1} / 2</span></div><h2>{page===0?t('كل ختم، نافذة جديدة.','Every stamp, a new window.'):t('رحلات وتجارب.','Journeys and encounters.')}</h2><div className="stamp-grid">{(page===0?['adhan','wudu','iqamah','congregational-prayer']:['khutbah','journey-call-to-prayer']).map((id,i)=>{const stampId=id.startsWith('journey')?id:'moment-'+id,won=stamps.find(s=>s.id===stampId);return <button className={'passport-stamp '+(won?'earned':'locked')+' stamp-'+i+(celebrate===stampId?' just-earned':'')} key={id} onClick={()=>{if(id.startsWith('journey'))go('journeys');else openMoment(id);}}><span className="stamp-ring">{id.startsWith('journey')?<Footprints size={27}/>:<Icon name={id==='wudu'?'water':id==='congregational-prayer'?'people':id==='khutbah'?'book':'audio'} size={27}/>}<strong>{id.startsWith('journey')?t('رحلة النداء','Call journey'):momentName(id)}</strong><small>{won?new Intl.DateTimeFormat(ar?'ar-SA-u-nu-latn':'en',{day:'numeric',month:'short',calendar:'gregory'}).format(new Date(won.at)):t('بانتظار لحظتك','WAITING FOR YOU')}</small></span><small className="stamp-help">{won?t('أضفته إلى فهمك','Added to your understanding'):id.startsWith('journey')?t('أكمل الرحلة لنيل الختم','Complete the journey to earn it'):t('افهم اللحظة لنيل الختم','Explore the source-verified explanation')}</small></button>;})}</div><div className="passport-bottom"><span>لَحْظَة</span><span>••• {String(page+1).padStart(2,'0')} •••</span></div></section><div className="passport-pagination"><button className="outlined" disabled={page===0} onClick={()=>setPage(0)}>{t('الصفحة السابقة','Previous page')}</button><button className="outlined" disabled={page===1} onClick={()=>setPage(1)}>{t('الصفحة التالية','Next page')}</button></div><button className="primary" onClick={async()=>{try{const epoch=dataEpoch.current;const exported=await exportPassport(stamps.filter(s=>s.type!=='visit-demo').map(s=>({...s,label:s.id.startsWith('journey')?txt(journey):momentName(s.id.replace('moment-',''))})),prefs.lang);if(epoch!==dataEpoch.current){URL.revokeObjectURL(exported.url);return;}setPassportImage(exported);setToast(t('صورة الجواز جاهزة.','Your passport image is ready.'));}catch{setToast(t('تعذّر إنشاء الصورة. أعد المحاولة.','Could not create the image. Please retry.'));}}}><Share2 size={20}/>{t('شارك جوازك صورة','Share your passport image')}</button><p className="fine-print">{t('جوازك لا يتضمن اسمًا أو موقعًا أو محادثات.','Your passport contains no name, location or conversations.')}</p>{page===1&&<TourEntry/>}</>}
